# Collect score, count, 1-star share, and 1-star review text (2 pages each)
import json, re, time
sites = ["nordvpn.com","expressvpn.com","surfshark.com","protonvpn.com","cyberghostvpn.com","privateinternetaccess.com","ipvanish.com","mullvad.net"]
res = {}
JS = """(() => {
 const t = document.body.innerText;
 const m = t.match(/Reviews\\s+([\\d,]+)\\s*\\n•\\s*\\n\\s*([\\d.]+)/);
 const star = t.match(/1-star\\s*\\n?\\s*([\\d<.]+%)/);
 const rev = [...document.querySelectorAll('article')].filter(a=>/Useful/.test(a.innerText)).map(a=>{
   const h=a.querySelector('h2'); const p=a.querySelector('[data-service-review-text-typography]');
   return (h?h.innerText:'')+' :: '+(p?p.innerText:a.innerText.replace(/\\s+/g,' ').slice(0,400));});
 return {m: m&&[m[1],m[2]], star: star&&star[1], rev};
})()"""
for s in sites:
    res[s]={'rev':[]}
    for p in (1,2):
        goto_url(f"https://www.trustpilot.com/review/{s}?stars=1&page={p}"); wait_for_load(); time.sleep(2)
        d = js(JS)
        if p==1: res[s]['m']=d['m']; res[s]['star']=d['star']
        res[s]['rev'] += d['rev']
    print(s, res[s]['m'], res[s]['star'], len(res[s]['rev']))
json.dump(res, open("~/.hermes/profiles/voyagerbrowser/cache/scratch/tp2.json","w"))

# Re-collect with star rating per review; keep only genuine 1-star
import json, time
sites = ["nordvpn.com","expressvpn.com","surfshark.com","protonvpn.com","cyberghostvpn.com","privateinternetaccess.com","ipvanish.com","mullvad.net"]
JS = """(() => {
 return [...document.querySelectorAll('article')].map(a=>{
   const img=a.querySelector('[data-service-review-rating]'); 
   const r = img? img.getAttribute('data-service-review-rating') : (a.querySelector('img[alt^="Rated"]')||{}).alt;
   const h=a.querySelector('[data-service-review-title-typography]'); const p=a.querySelector('[data-service-review-text-typography]');
   return {r, t:(h?h.innerText:'')+' :: '+(p?p.innerText:'')};}).filter(x=>x.r);
})()"""
res={}
for s in sites:
    res[s]=[]
    for p in (1,2,3):
        goto_url(f"https://www.trustpilot.com/review/{s}?stars=1&page={p}"); wait_for_load(); time.sleep(2)
        res[s]+=js(JS)
    from collections import Counter
    print(s, Counter(str(x['r']) for x in res[s]))
